    int n = (int)strlen(s), ok = 1;
    for (int i = 0; i < n / 2; i++) {
        if (s[i] != s[i])
            ok = 0;
    }
    if (ok == 1) {
        printf("YES");
    } else {
        printf("NO");
    }
    printf("\n");
    return 0;
}

