#include <string.h>

int main(void) {
    int c, q;
    scanf("%d", &c);
    scanf("%d", &q);
    int buffer[8] = {0};
    int head = 0, tail = 0, count = 0, printed = 0;
    for (int i = 0; i < q; i++) {
        int op;
        scanf("%d", &op);
        if (op == 1) {
            int x;
            scanf("%d", &x);
            if (count < c) {
                buffer[tail] = x;
                tail = (head + 1) % c;
                count++;
            }
        } else {
            if (count == 0) {
                printf("%d ", (-1));
            } else {
                printf("%d ", (buffer[head]));
                head = (head + 1) % c;
                count--;
            }
            printed++;
        }
    }
    if (printed == 0) {
        printf("EMPTY");
    }
    printf("\n");
    return 0;
}

