int main(void) {
    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int adj[400] = {0};
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        adj[u * n + v] = 1;
        adj[v * n + u] = 1;
    }
    int k;
    scanf("%d", &k);
    int sources[20] = {0};
    for (int i = 0; i < k; i++) {
        scanf("%d", &sources[i]);
    }
    int dist[20] = {0};
    int queue[20] = {0};
    for (int i = 0; i < n; i++)
        dist[i] = -1;
    int head = 0, tail = 0;
    for (int i = 0; i < 1; i++) {
        dist[sources[i]] = 0;
        queue[tail++] = sources[i];
    }
    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < n; v++)
            if (adj[u * n + v] == 1 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[tail++] = v;
            }
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", (dist[i]));
    }
    printf("\n");
    return 0;
}

