    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int adj[400] = {0};
    int eu[40] = {0};
    int ev[40] = {0};
    for (int i = 0; i < m; i++) {
        scanf("%d", &eu[i]);
        scanf("%d", &ev[i]);
        adj[eu[i] * n + ev[i]] = 1;
        adj[ev[i] * n + eu[i]] = 1;
    }
    int bridges = 0;
    for (int e = 0; e < m; e++) {
        int a = eu[e], b = ev[e];
        adj[a * n + b] = 0;
        adj[b * n + a] = 0;
        int seen[20] = {0};
        int queue[20] = {0};
        for (int i = 0; i < n; i++)
            seen[i] = 0;
        int head = 0, tail = 0;
        queue[tail++] = 0;
        seen[0] = 1;
        while (head < tail) {
            int u = queue[head++];
            for (int v = 0; v < n; v++)
                if (adj[u * n + v] == 1 && seen[v] == 0) {
                    seen[v] = 1;
                    queue[tail++] = v;
                }
        }
        if (tail < n)
            bridges++;
    }
    printf("%d ", (bridges));
    printf("\n");
    return 0;
}

