        int n, m;
        n = scanner.nextInt();
        m = scanner.nextInt();
        int[] adj = new int[400];
        int[] eu = new int[40];
        int[] ev = new int[40];
        for (int i = 0; i < m; i++) {
            eu[i] = scanner.nextInt();
            ev[i] = scanner.nextInt();
            adj[eu[i] * n + ev[i]] = 1;
            adj[ev[i] * n + eu[i]] = 1;
        }
        int bridges = 0;
        for (int e = 0; e < m; e++) {
            int a = eu[e], b = ev[e];
            adj[a * n + b] = 0;
            adj[b * n + a] = 0;
            int[] seen = new int[20];
            int[] queue = new int[20];
            for (int i = 0; i < n; i++)
                seen[i] = 0;
            int head = 0, tail = 0;
            queue[tail++] = 0;
            seen[0] = 1;
            while (head < tail) {
                int u = queue[head++];
                for (int v = 0; v < n; v++)
                    if (adj[u * n + v] == 1 && seen[v] == 0) {
                        seen[v] = 1;
                        queue[tail++] = v;
                    }
            }
            if (tail < n)
                bridges++;
        }
        System.out.print((bridges) + " ");
        System.out.println();
    }
}

